package exporter

import (
	"context"
	"fmt"
	"sort"
)

// dataSourceData is a minimal ResourceDataWrapper for objects of DataSourceOnly importables, which
// have no corresponding resource in the provider. It holds the top-level attributes used for naming
// and reference resolution. HCL code for such objects is generated by the Body function.
type dataSourceData struct {
	id    string
	attrs map[string]any
}

func newDataSourceData(id string, attrs map[string]any) *dataSourceData {
	if attrs == nil {
		attrs = map[string]any{}
	}
	return &dataSourceData{id: id, attrs: attrs}
}

func (d *dataSourceData) GetOk(key string) (interface{}, bool) {
	v, ok := d.attrs[key]
	return v, ok
}

func (d *dataSourceData) Get(key string) interface{} {
	return d.attrs[key]
}

func (d *dataSourceData) Id() string {
	return d.id
}

func (d *dataSourceData) SetId(id string) {
	d.id = id
}

func (d *dataSourceData) Set(key string, value interface{}) error {
	d.attrs[key] = value
	return nil
}

func (d *dataSourceData) GetSchema() SchemaWrapper {
	fields := make([]string, 0, len(d.attrs))
	for k := range d.attrs {
		fields = append(fields, k)
	}
	sort.Strings(fields)
	return &dataSourceSchema{fields: fields}
}

func (d *dataSourceData) IsPluginFramework() bool {
	return true
}

func (d *dataSourceData) GetTypedStruct(ctx context.Context, target interface{}) error {
	return fmt.Errorf("typed struct isn't supported for data source %s", d.id)
}

// dataSourceSchema exposes only the names of the attributes stored in dataSourceData.
type dataSourceSchema struct {
	fields []string
}

func (s *dataSourceSchema) GetFields() []string {
	return s.fields
}

func (s *dataSourceSchema) GetField(field string) FieldSchema {
	return nil
}

func (s *dataSourceSchema) IsPluginFramework() bool {
	return true
}
